const { app, BrowserWindow } = require('electron');
const fs = require('node:fs');
const path = require('node:path');
const mode = process.argv[2];
const output = process.argv[3];
app.setPath('userData', output + '.profile');
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width:1280, height:800, show:false, focusable:false, skipTaskbar:true, webPreferences:{ sandbox:true, contextIsolation:true, nodeIntegration:false, backgroundThrottling:false, offscreen:mode !== 'canvas-hidden' } });
  await win.loadFile(path.join(__dirname, 'closure-canvas.html'));
  if (mode !== 'idle-offscreen') await win.webContents.executeJavaScript('startCanvas()');
  const samples=[];
  const started=Date.now();
  let prior;
  let stopping=false;
  const finish=(reason) => {
    if (stopping) return;
    stopping=true;
    clearInterval(timer);
    fs.writeFileSync(output, JSON.stringify({ mode, versions:process.versions, noAppCode:true, noPlaywright:true, caps:{rssMiB:1536,cpuPercentOneCore:135,durationMs:20000}, reason, samples },null,2));
    win.destroy();
    app.quit();
  };
  const timer=setInterval(() => {
    const at=Date.now();
    const processes=app.getAppMetrics().map(p=>({pid:p.pid,type:p.type,rssMiB:p.memory.workingSetSize/1024,cpuSeconds:p.cpu.cumulativeCPUUsage}));
    const rssMiB=processes.reduce((sum,p)=>sum+p.rssMiB,0);
    const cpuPercentOneCore=prior ? 100000*processes.reduce((sum,p)=>sum+Math.max(0,p.cpuSeconds-(prior.processes.find(old=>old.pid===p.pid)?.cpuSeconds??p.cpuSeconds)),0)/(at-prior.at) : 0;
    const sample={at,elapsedMs:at-started,rssMiB,cpuPercentOneCore,mainMemory:process.memoryUsage(),processes};
    samples.push(sample);
    fs.writeFileSync(output+'.checkpoint.json',JSON.stringify({mode,samples},null,2));
    prior=sample;
    if (rssMiB>1536||cpuPercentOneCore>135) finish('resource-cap');
    else if(at-started>=20000) finish('completed');
  },500);
});

