import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
const require=createRequire(import.meta.url);
const executable=process.argv[2]??require('electron');
for(const mode of process.argv[3]?[process.argv[3]]:['idle-offscreen','canvas-offscreen','canvas-hidden']){
 const output=resolve(import.meta.dirname,(process.argv[4]??'')+mode+'.json');
 const child=spawn(executable,[resolve(import.meta.dirname,'closure-canvas.cjs'),mode,output],{windowsHide:true,stdio:['ignore','pipe','pipe']});
 let errors='';child.stderr.on('data',b=>{errors+=b.toString()});
 const code=await new Promise(done=>child.once('exit',done));
 if(code!==0) throw new Error(mode+' exited '+code+': '+errors.slice(-1000));
 const r=JSON.parse(readFileSync(output,'utf8'));
 console.log(JSON.stringify({mode,reason:r.reason,firstRssMiB:r.samples[0].rssMiB,lastRssMiB:r.samples.at(-1).rssMiB,maxRssMiB:Math.max(...r.samples.map(s=>s.rssMiB)),mainFirst:r.samples[0].mainMemory,mainLast:r.samples.at(-1).mainMemory}));
}
